let file = """{"version":3,"file":"UserPanel-C_tfMtVq.js","names":["$t","$t"],"sources":["../../src/platform/auth/session/components/SignOutEverywhereButton.vue","../../src/platform/auth/session/components/SignOutEverywhereButton.vue","../../src/components/dialog/content/setting/UserPanel.vue","../../src/components/dialog/content/setting/UserPanel.vue"],"sourcesContent":["<template>\n  <Button\n    v-if=\"webSession.signedInUser\"\n    variant=\"destructive-textonly\"\n    :loading=\"signingOut\"\n    @click=\"signOutEverywhere\"\n  >\n    {{ $t('auth.signOutEverywhere.action') }}\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport {\n  useCloudWebSessionStore,\n  webSessionFailureMessage\n} from '@/platform/auth/session/cloudWebSessionStore'\n\nconst { t } = useI18n()\nconst { logout } = useAuthActions()\nconst webSession = useCloudWebSessionStore()\nconst toast = useToast()\nconst signingOut = ref(false)\n\nasync function revokeAllSessions(): Promise<boolean> {\n  const result = await webSession.revokeAllSessions()\n  if (result.status === 'error') {\n    toast.error(t('auth.signOutEverywhere.failed'), {\n      description: webSessionFailureMessage(result.code),\n      duration: 8000\n    })\n    return false\n  }\n  toast.success(t('auth.signOutEverywhere.success'), {\n    description: t('auth.signOutEverywhere.successDetail'),\n    duration: 5000\n  })\n  return true\n}\n\nasync function signOutEverywhere() {\n  signingOut.value = true\n  try {\n    await logout({ beforeSignOut: revokeAllSessions })\n  } finally {\n    signingOut.value = false\n  }\n}\n</script>\n","<template>\n  <Button\n    v-if=\"webSession.signedInUser\"\n    variant=\"destructive-textonly\"\n    :loading=\"signingOut\"\n    @click=\"